import{_ as a,o,c as t,a2 as r}from"./chunks/framework.DaAAbehN.js";const g=JSON.parse('{"title":"About Codex Course","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),l={name:"about.md"};function i(n,e,s,u,d,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="about-codex-course" tabindex="-1">About Codex Course <a class="header-anchor" href="#about-codex-course" aria-label="Permalink to &quot;About Codex Course&quot;">​</a></h1><h2 id="关于课程" tabindex="-1">关于课程 <a class="header-anchor" href="#关于课程" aria-label="Permalink to &quot;关于课程&quot;">​</a></h2><p>This course is designed for absolute beginners who want to learn how to use OpenAI&#39;s Codex — an AI coding agent that can read files, write code, run commands, and automate tasks using natural language.</p><p><strong>No programming experience required.</strong> If you can speak naturally, you can use Codex to complete practical tasks.</p><h3 id="course-contents" tabindex="-1">Course Contents <a class="header-anchor" href="#course-contents" aria-label="Permalink to &quot;Course Contents&quot;">​</a></h3><ul><li><strong>Module 1:</strong> Understanding Codex (3 lessons)</li><li><strong>Module 2:</strong> Getting Started (4 lessons)</li><li><strong>Module 3:</strong> Core Features (4 lessons)</li><li><strong>Module 4:</strong> Practical Tips (3 lessons)</li><li><strong>Module 5:</strong> Project Practice (4 projects)</li><li><strong>Module 6:</strong> Summary &amp; Next Steps (2 lessons)</li></ul><h3 id="what-you-ll-learn" tabindex="-1">What You&#39;ll Learn <a class="header-anchor" href="#what-you-ll-learn" aria-label="Permalink to &quot;What You&#39;ll Learn&quot;">​</a></h3><ul><li>File operations: organize folders, batch rename, classify files</li><li>Natural language programming: describe needs in plain language, let Codex generate code</li><li>Web search: let Codex search the internet and compile reports</li><li>Automation: let Codex handle repetitive tasks</li><li>Skills: use built-in skills to complete complex tasks (like generating PPTs)</li></ul><h3 id="target-audience" tabindex="-1">Target Audience <a class="header-anchor" href="#target-audience" aria-label="Permalink to &quot;Target Audience&quot;">​</a></h3><ul><li>Professionals with zero programming background</li><li>Content creators who want to automate their workflow</li><li>Anyone who wants to leverage AI for productivity</li></ul><hr><h2 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to &quot;课程定位&quot;">​</a></h2><p>面向零编程基础的职场人士和内容创作者，让学员理解 Codex 是什么、能做什么，并能独立用 Codex 完成实际任务。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>理解 AI 编程助手与聊天机器人的区别</li><li>掌握 Codex 的安装、登录和基本操作</li><li>能用自然语言指挥 Codex 完成文件操作、数据分析、网页生成等任务</li><li>独立完成 4 个实战项目</li></ul><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><ul><li>GitHub: <a href="https://github.com/qlxxkj/CodexCourse" target="_blank" rel="noreferrer">qlxxkj/CodexCourse</a></li><li>反馈与建议: <a href="/CodexCourse/appendix/feedback.html">课后反馈表</a></li></ul>',17)])])}const p=a(l,[["render",i]]);export{g as __pageData,p as default};
